-- YT watch flow v7 (2026-10-08): re-query the expander after scrolling; live evidence showed the pre-scroll ref goes stale and the trusted click fails while the synthetic one silently no-ops.
-- v6 note kept: flattened open cascade, every post-watch wait tolerated; live evidence showed the transcript hunt dying on caption-less videos and one await outliving the statement timeout.
-- Worst case degrades to page-text chunks, never a hard failure past the watch waits.

-- No public MCP tool/schema, protocol, primitive, VM, signing, auth, or transport boundary changes are introduced here.

select public.opera_register_workflow(
  'youtube.watch_summarize',
  $wf${"steps":[{"id":"open","type":"command","method":"tabs.open","params":{"url":{"$ref":"input.url"},"active":false,"wait":true}},{"name":"tabId","type":"set","value":{"$ref":"steps.open.result.tab.id"}},{"id":"watch","type":"command","method":"page.wait_for","params":{"tabId":{"$ref":"vars.tabId"},"selector":"ytd-watch-flexy","timeoutMs":15000}},{"id":"watchAgain","type":"command","method":"page.wait_for","params":{"tabId":{"$ref":"vars.tabId"},"selector":"ytd-watch-flexy","timeoutMs":15000},"continueOnError":true},{"name":"panelWasOpen","type":"set","value":false},{"name":"openMethod","type":"set","value":"none"},{"name":"activatedForRender","type":"set","value":false},{"id":"panel","type":"command","method":"page.query","params":{"index":0,"limit":5,"tabId":{"$ref":"vars.tabId"},"selector":"ytd-transcript-renderer, ytd-engagement-panel-section-list-renderer[target-id*=transcript][visibility=ENGAGEMENT_PANEL_VISIBILITY_EXPANDED]","visibleOnly":false},"continueOnError":true},{"id":"expand","type":"command","method":"page.query","params":{"index":0,"limit":5,"tabId":{"$ref":"vars.tabId"},"selector":"#description-inline-expander #expand, ytd-text-inline-expander #expand, tp-yt-paper-button#expand","visibleOnly":false},"continueOnError":true},{"id":"openExpander","type":"if","condition":{"op":"exists","left":{"$ref":"steps.expand.result.item"}},"then":[{"id":"expandFresh","type":"command","method":"page.query","params":{"index":0,"limit":5,"tabId":{"$ref":"vars.tabId"},"selector":"#description-inline-expander #expand, ytd-text-inline-expander #expand, tp-yt-paper-button#expand","visibleOnly":false},"continueOnError":true},{"id":"scrollExpand","type":"command","method":"page.scroll","params":{"ref":{"$ref":"steps.expand.result.item.ref"},"tabId":{"$ref":"vars.tabId"},"block":"center"},"continueOnError":true},{"id":"clickExpand","type":"command","method":"page.click","params":{"ref":{"$ref":"steps.expandFresh.result.item.ref"},"tabId":{"$ref":"vars.tabId"},"trusted":false},"continueOnError":true},{"id":"clickExpandTrusted","type":"command","method":"page.click","params":{"ref":{"$ref":"steps.expandFresh.result.item.ref"},"tabId":{"$ref":"vars.tabId"},"trusted":true},"continueOnError":true}],"else":[]},{"id":"panelCheck","type":"command","method":"page.wait_for","params":{"tabId":{"$ref":"vars.tabId"},"selector":"ytd-transcript-renderer, ytd-engagement-panel-section-list-renderer[target-id*=transcript][visibility=ENGAGEMENT_PANEL_VISIBILITY_EXPANDED]","timeoutMs":3000,"visibleOnly":false},"continueOnError":true},{"id":"panelNote","type":"if","condition":{"op":"exists","left":{"$ref":"steps.panelCheck.result.item"}},"then":[{"name":"openMethod","type":"set","value":"expanded"}],"else":[]},{"id":"panelWas","type":"if","condition":{"op":"exists","left":{"$ref":"steps.panel.result.item"}},"then":[{"name":"panelWasOpen","type":"set","value":true},{"name":"openMethod","type":"set","value":"already-open"}],"else":[]},{"id":"segmentFast","type":"command","method":"page.wait_for","params":{"tabId":{"$ref":"vars.tabId"},"selector":"ytd-transcript-segment-renderer","timeoutMs":1200,"visibleOnly":false},"continueOnError":true},{"id":"renderHelp","type":"if","condition":{"op":"not_exists","left":{"$ref":"steps.segmentFast.result.item"}},"then":[{"id":"prevActive","type":"command","method":"tabs.get","params":{"tabId":{"$ref":"vars.tabId"}}},{"id":"activateForRender","type":"command","method":"tabs.activate","params":{"tabId":{"$ref":"vars.tabId"},"focusWindow":false}},{"name":"prevActiveId","type":"set","value":{"$ref":"steps.prevActive.result.tab.id"}},{"name":"activatedForRender","type":"set","value":true},{"id":"segmentReady","type":"command","method":"page.wait_for","params":{"tabId":{"$ref":"vars.tabId"},"selector":"ytd-transcript-segment-renderer","timeoutMs":6000,"visibleOnly":false},"continueOnError":true}],"else":[]},{"id":"segments","type":"command","method":"page.query","params":{"limit":100,"tabId":{"$ref":"vars.tabId"},"selector":"ytd-transcript-segment-renderer","visibleOnly":false},"continueOnError":true},{"id":"segmentsAvailable","type":"if","condition":{"op":"truthy","left":{"$ref":"steps.segments.result.count"}},"then":[],"else":[{"name":"text","type":"set","value":""},{"name":"offset","type":"set","value":0},{"id":"chunks","type":"repeat","steps":[{"id":"read","type":"command","method":"page.read","params":{"limit":12000,"tabId":{"$ref":"vars.tabId"},"offset":{"$ref":"vars.offset"},"maxElements":1,"includeElements":false}},{"name":"text","type":"set","value":{"$concat":[{"$ref":"vars.text"},{"$ref":"steps.read.result.page.text"}]}},{"name":"offset","type":"set","value":{"$ref":"steps.read.result.page.nextOffset"}}],"until":{"op":"falsey","left":{"$ref":"steps.read.result.page.hasMore"}},"failOnLimit":false,"maxIterations":30}]},{"id":"tab","type":"command","method":"tabs.get","params":{"tabId":{"$ref":"vars.tabId"}}},{"id":"restore","type":"if","condition":{"op":"truthy","left":{"$ref":"vars.activatedForRender"}},"then":[{"id":"restoreActive","type":"command","method":"tabs.activate","params":{"tabId":{"$ref":"vars.prevActiveId"},"focusWindow":false},"continueOnError":true}],"else":[]}],"output":{"title":{"$ref":"steps.tab.result.tab.title"},"url":{"$ref":"steps.tab.result.tab.url"},"segments":{"$ref":"steps.segments.result.items"},"segmentCount":{"$ref":"steps.segments.result.count"},"text":{"$ref":"vars.text"},"openMethod":{"$ref":"vars.openMethod"},"panelWasOpen":{"$ref":"vars.panelWasOpen"},"activatedForRender":{"$ref":"vars.activatedForRender"}}}$wf$,
  'Open a YouTube URL in a background tab and return its transcript payload (segments with text, or page text fallback) plus title and open metadata, in one supervised run.',
  true
);
